WORDS = []
for item in RAW.split('|'):
    w, s, e = item.rsplit(' ', 2)
    WORDS.append({'word': w, 'start': float(s), 'end': float(e)})
if __name__ == '__main__':
    import sys
    off = float(sys.argv[1])
    json.dump({'words': [{'word': x['word'], 'start': round(x['start'] + off, 3), 'end': round(x['end'] + off, 3)} for x in WORDS]},
              open('words.json', 'w'), ensure_ascii=False)
    print(len(WORDS))
